/**
 * Node: math.min
 * Computes minimum of two numbers
 */

const { defineInputPort, defineOutputPort, PortTypes } = require("../../contracts/ports");

module.exports = {
  type: "math.min",
  version: "1.0.0",
  category: "math",
  label: "Minimum",
  description: "Returns the lesser of two numbers (min(a, b))",
  inputs: {
    a: defineInputPort({ name: "a", type: PortTypes.NUMBER, required: true, description: "First number" }),
    b: defineInputPort({ name: "b", type: PortTypes.NUMBER, required: true, description: "Second number" }),
  },
  outputs: {
    result: defineOutputPort({ name: "result", type: PortTypes.NUMBER, description: "Minimum result" }),
  },
  validateConfig: () => ({ valid: true }),
  capabilities: { pure: true, sideEffects: false, retryable: true },
  handler: async (inputs) => {
    return { result: Math.min(Number(inputs.a), Number(inputs.b)) };
  },
};
